/* Driver for the C-entry kernels generated by gen.py.
 *
 *   centry sizes                       bytes and fused uops of every routine, both copies
 *   centry run PATTERN[,PATTERN...]    run the kernels whose names match (fnmatch)
 *
 * Environment: RF_CPU (default 13) the CPU to pin to, RF_WATCH (default 29) CPUs whose
 * utilisation is reported, RF_ITERS (default 10M) operations per run, RF_REPS (default 4)
 * repetitions per round (the first warms up), RF_ROUNDS (default 3) interleaved rounds,
 * RF_SIZES (default 32) the sizes the fixed-size kernels pass to malloc.
 *
 * Each cell is the fastest repetition over all rounds; `+x` is how much slower the slowest
 * round's best was. A run that aborted its sequences more than once per thousand operations
 * does not count.
 */
#define _GNU_SOURCE
#include <errno.h>
#include <fnmatch.h>
#include <linux/perf_event.h>
#include <sched.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/rseq.h>
#include <sys/syscall.h>
#include <unistd.h>

#include "classes.h"
#include "table.h"

#define NCOUNT 5
static int fds[NCOUNT] = {-1, -1, -1, -1, -1};
static const char *count_names[NCOUNT] = {"cyc", "ins", "uops", "dec", ""};

static int counter(uint32_t type, uint64_t config) {
    struct perf_event_attr a;
    memset(&a, 0, sizeof a);
    a.size = sizeof a;
    a.type = type;
    a.config = config;
    a.disabled = 1;
    a.exclude_kernel = 1;
    a.exclude_hv = 1;
    return (int)syscall(SYS_perf_event_open, &a, 0, -1, -1, 0);
}

static void start(void) {
    for (int i = 0; i < NCOUNT; i++)
        if (fds[i] >= 0) {
            ioctl(fds[i], PERF_EVENT_IOC_RESET, 0);
            ioctl(fds[i], PERF_EVENT_IOC_ENABLE, 0);
        }
}

static void stop(uint64_t v[NCOUNT]) {
    for (int i = NCOUNT - 1; i >= 0; i--) {
        v[i] = 0;
        if (fds[i] >= 0) {
            ioctl(fds[i], PERF_EVENT_IOC_DISABLE, 0);
            if (read(fds[i], &v[i], 8) != 8) v[i] = 0;
        }
    }
}

/* ---- the heap the kernels see ---- */

static uintptr_t heap_base;
enum { SHIFT = 32 };
static struct front_data copies[2];
static uint64_t words[2][SMALL + 1];
static int cpu;

static void *map(size_t len, int prot, int flags) {
    void *p = mmap(NULL, len, prot, MAP_PRIVATE | MAP_ANONYMOUS | flags, -1, 0);
    if (p == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }
    return p;
}

/* A magazine per small class, half full, loaded on this CPU. Objects are addresses in their
 * class's region; nothing touches them. */
static void prepare(int which) {
    struct front_data *d = &copies[which];
    static char *mags[2][SMALL + 1];
    for (unsigned c = 1; c <= SMALL; c++) {
        unsigned n = mag_slots(c);
        if (!mags[which][c]) {
            char *raw = map(16 * n, PROT_READ | PROT_WRITE, 0);
            mags[which][c] = (char *)(((uintptr_t)raw + 8 * n - 1) & ~(uintptr_t)(8 * n - 1));
        }
        uint64_t *m = (uint64_t *)mags[which][c];
        unsigned fill = n / 2;
        for (unsigned k = 0; k < fill; k++) m[1 + k] = heap_base + ((uint64_t)c << SHIFT) + k * class_size(c);
        words[which][c] = (uint64_t)(uintptr_t)&m[1 + fill];
        *(uint64_t *)(d->slabs + ((size_t)cpu << 12) + 8 * c) = words[which][c];
    }
}

static void check(int which, const char *name) {
    struct front_data *d = &copies[which];
    for (unsigned c = 1; c <= SMALL; c++) {
        uint64_t w = *(uint64_t *)(d->slabs + ((size_t)cpu << 12) + 8 * c);
        if (w != words[which][c]) {
            fprintf(stderr, "%s: class %u slab word moved (%#lx, expected %#lx)\n", name, c, (unsigned long)w,
                    (unsigned long)words[which][c]);
            exit(1);
        }
    }
}

/* ---- running ---- */

static uint64_t env_u(const char *k, uint64_t dflt) {
    const char *v = getenv(k);
    return v ? strtoull(v, NULL, 0) : dflt;
}

struct meas {
    double v[NCOUNT];
};

static uint64_t arr[256];
static uint32_t mixed[64];

static struct meas measure(const struct kernel *k, uint64_t size) {
    uint64_t iters = env_u("RF_ITERS", 10000000), reps = env_u("RF_REPS", 4);
    uint64_t n = iters / k->ops;
    if (n == 0) n = 1;
    struct meas best = {{1e300}};
    for (uint64_t r = 0; r < reps; r++) {
        prepare(0);
        prepare(1);
        uint64_t a0 = *(uint64_t *)copies[0].abort_count + *(uint64_t *)copies[1].abort_count;
        uint64_t v[NCOUNT];
        start();
        k->f(n, arr, size, mixed);
        stop(v);
        uint64_t aborts = *(uint64_t *)copies[0].abort_count + *(uint64_t *)copies[1].abort_count - a0;
        check(0, k->name);
        check(1, k->name);
        double ops = (double)(n * k->ops);
        if ((r > 0 || reps == 1) && aborts * 1000 < n * k->ops && v[0] / ops < best.v[0])
            for (int i = 0; i < NCOUNT; i++) best.v[i] = v[i] / ops;
    }
    return best;
}

static void cpu_times(uint64_t *total, uint64_t *idle, int ncpu) {
    FILE *f = fopen("/proc/stat", "r");
    char line[512];
    while (f && fgets(line, sizeof line, f)) {
        int c;
        unsigned long long u[10] = {0};
        if (sscanf(line, "cpu%d %llu %llu %llu %llu %llu %llu %llu %llu", &c, &u[0], &u[1], &u[2], &u[3], &u[4],
                   &u[5], &u[6], &u[7]) >= 5 &&
            c < ncpu) {
            total[c] = 0;
            for (int i = 0; i < 8; i++) total[c] += u[i];
            idle[c] = u[3] + u[4];
        }
    }
    if (f) fclose(f);
}

static void sizes(void) {
    const struct routine *t[2] = {ROUTINES_L_, ROUTINES_X_};
    size_t n = sizeof ROUTINES_L_ / sizeof ROUTINES_L_[0];
    printf("%-10s %-7s %8s %8s %6s\n", "routine", "kind", "lib B", "exe B", "uops");
    for (size_t i = 0; i < n; i++) {
        long a = (const char *)t[0][i].end - (const char *)t[0][i].entry;
        long b = (const char *)t[1][i].end - (const char *)t[1][i].entry;
        printf("%-10s %-7s %8ld %8ld %6d%s\n", t[0][i].name, t[0][i].kind, a, b, t[0][i].uops,
               ((uintptr_t)t[0][i].entry % 64 || (uintptr_t)t[1][i].entry % 64) ? "  (not 64-aligned!)" : "");
    }
}

static int matches(const char *name, const char *pats) {
    char buf[1024];
    snprintf(buf, sizeof buf, "%s", pats);
    for (char *p = strtok(buf, ","); p; p = strtok(NULL, ","))
        if (fnmatch(p, name, 0) == 0) return 1;
    return 0;
}

int main(int argc, char **argv) {
    cpu = (int)env_u("RF_CPU", 13);
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    if (sched_setaffinity(0, sizeof set, &set)) {
        perror("sched_setaffinity");
        return 1;
    }
    if (__rseq_size == 0) {
        fprintf(stderr, "glibc did not register rseq\n");
        return 1;
    }
    volatile struct rseq *rs = (struct rseq *)((char *)__builtin_thread_pointer() + __rseq_offset);
    if (getenv("RF_VERBOSE")) fprintf(stderr, "rseq area %p (page offset %#lx), __rseq_offset %ld\n", (void *)rs, (unsigned long)((uintptr_t)rs & 4095), (long)__rseq_offset);
    if ((int)rs->cpu_id != cpu) {
        fprintf(stderr, "rseq cpu_id %d, pinned to %d\n", (int)rs->cpu_id, cpu);
        return 1;
    }
    L_data(&copies[0]);
    X_data(&copies[1]);
    size_t span = (size_t)128 << SHIFT;
    uintptr_t raw = (uintptr_t)map(span, PROT_NONE, MAP_NORESERVE);
    heap_base = (raw + ((uintptr_t)1 << SHIFT) - 1) & ~(((uintptr_t)1 << SHIFT) - 1);
    setup_tables(&copies[0], heap_base, SHIFT);
    setup_tables(&copies[1], heap_base, SHIFT);
    /* RF_MIXED=lo,hi[,period]: the mixed loop's 64 sizes, uniform in lo..hi (default 1..512),
     * repeating every `period` entries (default 64). */
    unsigned lo = 1, hi = 512, period = 64;
    if (getenv("RF_MIXED")) sscanf(getenv("RF_MIXED"), "%u,%u,%u", &lo, &hi, &period);
    if (period < 1 || period > 64 || 64 % period) period = 64;
    srand(1);
    for (int i = 0; i < 64; i++) mixed[i] = i < (int)period ? lo + (uint32_t)(rand() % (hi - lo + 1)) : mixed[i % period];

    if (argc < 2 || strcmp(argv[1], "sizes") == 0) {
        sizes();
        return 0;
    }
    if (strcmp(argv[1], "run") != 0 || argc < 3) {
        fprintf(stderr, "usage: centry sizes | centry run PATTERN[,PATTERN...]\n");
        return 2;
    }
    fds[0] = counter(PERF_TYPE_HARDWARE, PERF_COUNT_HW_CPU_CYCLES);
    /* RF_COUNTERS: up to four of ins, uops (retired ops), dec (ops dispatched from the x86
     * decoder rather than the op cache), brmiss, or a raw AMD event as rXXXX. */
    char cbuf[256];
    snprintf(cbuf, sizeof cbuf, "%s", getenv("RF_COUNTERS") ? getenv("RF_COUNTERS") : "ins,uops,dec");
    int nc = 1;
    for (char *p = strtok(cbuf, ","); p && nc < NCOUNT; p = strtok(NULL, ","), nc++) {
        count_names[nc] = strdup(p);
        if (!strcmp(p, "ins")) fds[nc] = counter(PERF_TYPE_HARDWARE, PERF_COUNT_HW_INSTRUCTIONS);
        else if (!strcmp(p, "uops")) fds[nc] = counter(PERF_TYPE_RAW, 0xC1);
        else if (!strcmp(p, "dec")) fds[nc] = counter(PERF_TYPE_RAW, 0x01AA);
        else if (!strcmp(p, "brmiss")) fds[nc] = counter(PERF_TYPE_HARDWARE, PERF_COUNT_HW_BRANCH_MISSES);
        else if (p[0] == 'r') fds[nc] = counter(PERF_TYPE_RAW, strtoull(p + 1, NULL, 16));
        if (fds[nc] < 0) fprintf(stderr, "counter %s unavailable\n", p);
    }
    if (fds[0] < 0) {
        perror("perf_event_open");
        return 1;
    }

    uint64_t sz[16];
    int nsz = 0;
    char buf[256];
    snprintf(buf, sizeof buf, "%s", getenv("RF_SIZES") ? getenv("RF_SIZES") : "32");
    for (char *p = strtok(buf, ","); p && nsz < 16; p = strtok(NULL, ",")) sz[nsz++] = strtoull(p, NULL, 0);

    size_t nk = sizeof KERNELS / sizeof KERNELS[0];
    struct item {
        const struct kernel *k;
        uint64_t size;
        struct meas best;
        double worst;
    } *items = calloc(nk * 16, sizeof *items);
    size_t ni = 0;
    for (size_t i = 0; i < nk; i++) {
        if (!matches(KERNELS[i].name, argv[2])) continue;
        int fixed = strcmp(KERNELS[i].form, "mixed") != 0;
        for (int s = 0; s < (fixed ? nsz : 1); s++) {
            items[ni].k = &KERNELS[i];
            items[ni].size = fixed ? sz[s] : 0;
            items[ni].best.v[0] = 1e300;
            ni++;
        }
    }
    uint64_t t0[64] = {0}, i0[64] = {0}, t1[64] = {0}, i1[64] = {0};
    cpu_times(t0, i0, 64);
    uint64_t rounds = env_u("RF_ROUNDS", 3);
    for (uint64_t r = 0; r < rounds; r++)
        for (size_t i = 0; i < ni; i++) {
            struct meas m = measure(items[i].k, items[i].size);
            if (m.v[0] < items[i].best.v[0]) items[i].best = m;
            if (m.v[0] > items[i].worst) items[i].worst = m.v[0];
        }
    cpu_times(t1, i1, 64);
    printf("%-24s %-8s %-8s %-8s %-4s %5s %13s", "kernel", "form", "malloc", "free", "call", "size", "cyc/op");
    for (int c = 1; c < NCOUNT; c++)
        if (fds[c] >= 0) printf(" %7s", count_names[c]);
    printf("\n");
    for (size_t i = 0; i < ni; i++) {
        const struct kernel *k = items[i].k;
        printf("%-24s %-8s %-8s %-8s %-4s %5lu %7.2f +%-4.2f", k->name, k->form, k->m, k->f_, k->call,
               (unsigned long)items[i].size, items[i].best.v[0], items[i].worst - items[i].best.v[0]);
        for (int c = 1; c < NCOUNT; c++)
            if (fds[c] >= 0) printf(" %7.2f", items[i].best.v[c]);
        printf("\n");
    }
    const char *watch = getenv("RF_WATCH") ? getenv("RF_WATCH") : "29";
    snprintf(buf, sizeof buf, "%s", watch);
    printf("busy during run:");
    for (char *p = strtok(buf, ","); p; p = strtok(NULL, ",")) {
        int c = atoi(p);
        if (c < 0 || c >= 64 || t1[c] == t0[c]) continue;
        printf(" cpu%d %.1f%%", c, 100.0 * (1.0 - (double)(i1[c] - i0[c]) / (double)(t1[c] - t0[c])));
    }
    printf("\n");
    return 0;
}
